import React, { Component } from "react";
import "./Login.css";
import FormJson from "./formid";
import PagesJson from "./PagesJson";

export default class Login extends Component {
    constructor(props) {
        super(props);
        this.state = {
            activeTap:'signup',
            formData:{},
            buttonsdata:[],
            leftside:[],
            rightside:[],


            // loginpage: null,

        };
    }

    componentDidMount() {

        const pageName = "LogIn";
        fetch(`http://localhost:3001/${pageName}`)
            .then(response => response.json())
            .then(data => {
                const signupPage=data.pages.finde(page=>page.pageName)
                this.setState({ formData:data,
                    buttonsdata:data.content.button,
                    leftside:data.content.leftside,
                    rightside:data.content.rightside,

                 });
            })
            .catch(error => console.error('Error fetching data:', error));
    }
    setActiveTap=(tab)=>{
        this.setState({activeTap:tab})
    }
    render() {
        const {activeTab,formData,buttonsdata,leftside,rightside}=this.state
        const { loginpage } = this.state;
        if (!loginpage) return <div>PAGE NOT FOUND</div>;
  const { signupage } = this.state;
        const textLogin = loginpage.text;
        // const buttonsdata = loginpage.buttons;

        return (
            <div className="content-container">
                <div className="formboxx">
                    <div className="button-boxx">
                        <div id="btn"></div>
                        {buttonsdata.map((value, index) => (
                            <button
                                key={index}
                                type={value.type}
                                className={activeTab===`${value.text}`? 'active':'' }
                                onClick={()=>this.setActiveTap(`${value.text}`)}
                            >
                                {value.text}
                            </button>
                        ))}
                    </div>

                    <div className="social-icons">
                        <img src={loginpage.Img2} alt="social icon 1" />
                        <img src={loginpage.Img1} alt="social icon 2" />
                    </div>

                    {activeTab==='signup' &&(
     <form className="input-group">
     <div className="input-left">

         {leftside.map((item, index) => (
             <input
                 key={index}
                 type={item.type}
                 className={item.className}
                 placeholder={item.placeholder}
                 required
             />
         ))}
     </div>

     <div className="input-right">
         {rightside.map((item, index) => (
             <input
                 key={index}
                 type={item.type}
                 className={item.className}
                 placeholder={item.placeholder}
                 required
             />
         ))}
     </div>
 </form>

                    )

                    }

                        {

                        }
                        {/* {textLogin.map((item, index) => (
                            <input
                                key={index}
                                type={item.type}
                                className={item.className}
                                placeholder={item.placeholder}
                                required
                            />
                        ))} */}
                        <a href="#" className="forget">Forget/Change your password?</a>
                        <button type="submit" className="submit-btnn">Log in</button>

                </div>
            </div>
        );
    }
}
